<?php
require __DIR__.'/entreprise_init.php';
$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);
$s=$con->prepare("SELECT ec.*,u.nom_user,u.prenom_user,u.email_user,u.tel_user,u.date_inscrip_user FROM t_entreprise_collaborateurs ec INNER JOIN t_utilisateurs u ON u.id_user=ec.id_user WHERE ec.id_collaborateur=? AND ec.id_entreprise=? LIMIT 1");$s->execute([$id,$idEntreprise]);$r=$s->fetch();if(!$r)exit('Collaborateur introuvable.');
$s=$con->prepare("SELECT f.titre_form,i.date_inscrip_form,i.statut_inscrip FROM t_inscriptions i INNER JOIN t_formations f ON f.id_form=i.id_form WHERE i.id_user=? ORDER BY i.date_inscrip_form DESC");$s->execute([$r['id_user']]);$formations=$s->fetchAll();$active_page='collaborateurs.php';
?>
<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Collaborateur — TOUN</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"><link rel="stylesheet" href="entreprise-menu.css"><link rel="stylesheet" href="entreprise-ui.css"></head><body><?php include __DIR__.'/menu_entreprise.php';?><main class="main-content"><div class="page"><div class="page-head"><div><span class="eyebrow">COLLABORATEUR</span><h1><?=e(trim($r['prenom_user'].' '.$r['nom_user']))?></h1><p><?=e($r['email_user'])?></p></div><a class="btn btn-light" href="collaborateurs.php">Retour</a></div><div class="grid"><section class="card"><h2>Informations</h2><div class="list" style="margin-top:10px"><div class="list-item"><span>Nom complet</span><strong><?=e(trim($r['prenom_user'].' '.$r['nom_user']))?></strong></div><div class="list-item"><span>Téléphone</span><strong><?=e($r['tel_user']?:'—')?></strong></div><div class="list-item"><span>Ajouté le</span><strong><?=e(date('d/m/Y',strtotime($r['date_ajout'])))?></strong></div><div class="list-item"><span>Statut</span><strong><?=e($r['statut'])?></strong></div></div></section><section class="card"><h2>Formations</h2><div class="list" style="margin-top:10px"><?php if(!$formations):?><div class="empty">Aucune formation.</div><?php else:foreach($formations as $f):?><div class="list-item"><div><strong><?=e($f['titre_form'])?></strong><small><?=e($f['statut_inscrip'])?></small></div></div><?php endforeach;endif;?></div></section></div></div></main></body></html>